local def={
	on_merge = function(self, old_eff, new_eff)
		max = math.max(old_eff.max, new_eff.max)
		old_eff.power = math.min(old_eff.power + new_eff.power, max)
		self:removeTemporaryValue("global_speed_add", old_eff.tmpid)
		old_eff.tmpid = self:addTemporaryValue("global_speed_add", -old_eff.power)
		return old_eff
	end,
}
local actor={removeTemporaryValue=function()end,addTemporaryValue=function()return 1 end}
for _,d in ipairs({1,2,3})do local old={power=.8,max=.3,dur=d,tmpid=1};local new={power=.1,max=.3,dur=3};local merged=def.on_merge(actor,old,new);assert(merged==old and merged.power==.3 and merged.dur==d)end
print("PASS actual ECHOED_LIGHT on_merge caps strength but preserves old duration 1/2/3")
